:root {
  --spacing-scale-half: 4px;
  --spacing-scale-base: 8px;
  --spacing-scale-baseh: 12px;
  --spacing-scale-2x: 16px;
  --spacing-scale-2xh: 20px;
  --spacing-scale-3x: 24px;
  --spacing-scale-3xh: 28px;
  --spacing-scale-4x: 32px;
  --spacing-scale-4xh: 36px;
  --spacing-scale-5x: 40px;
  --spacing-scale-5xh: 44px;
  --spacing-scale-6x: 48px;
  --spacing-scale-7x: 56px;
  --spacing-scale-8x: 64px;
  --spacing-scale-9x: 72px;
  --spacing-scale-10x: 80px;
  --sidebar-width: 235px;
  --radius-none: 0px;
  --radius-pill: 999px;
  --bp-xs: 0px;
  --bp-sm: 576px;
  --bp-md: 992px;
  --bp-lg: 1280px;
  --bp-xl: 1600px;
  --container-sm-max: 536px;
  --container-md-max: 912px;
  --container-lg-max: 1200px;
  --container-xl-max: 1520px;
  --font-sans: "Noto Sans", system-ui, sans-serif;
  --font-display: "Noto Sans Display", "Noto Sans", system-ui, sans-serif;
  --font-mono: "Noto Sans Mono", ui-monospace, monospace;
}

0,700;0,800;1,400;1,700&family=Noto+Sans+Display:ital,wght@0,600;0,800;1,600;1,800&family=Noto+Sans+Mono:wght@400;600&display=swap");

/* =====================================================================
   DS Procempa — base (tipografia, densidade, grid)
   Densidade: 1rem = 16px (sites). <html class="sistemas"> → 1rem = 14px.
   ===================================================================== */
html.sistemas { font-size: 14px; }
.ds [hidden], .dis [hidden] { display: none !important; }
.ds, .ds *, .dis, .dis * { box-sizing: border-box; }
.ds, .dis { font-family: var(--font-sans); font-size: 1rem; line-height: 1.45; color: var(--neutral-body); background: var(--white); }
.ds button, .dis button, .ds input, .dis input { font-family: inherit; }

:where(.ds) h1, :where(.ds) .h1 { font-family: var(--font-display); font-weight: 800; font-size: 2.5rem; line-height: 1.15; color: var(--primary-surfaces); margin: 0 0 1rem; }
:where(.ds) h2, :where(.ds) .h2 { font-family: var(--font-display); font-weight: 600; font-size: 2.25rem; line-height: 1.15; color: var(--primary-headings); margin: calc(.5rem + 1em) 0 1rem; }
:where(.ds) h3, :where(.ds) .h3 { font-family: var(--font-display); font-weight: 600; font-size: 2rem; line-height: 1.15; color: var(--primary-headings); margin: calc(.5rem + 1em) 0 1rem; }
:where(.ds) h4, :where(.ds) .h4 { font-family: var(--font-display); font-weight: 600; font-size: 1.5rem; line-height: 1.15; color: var(--primary-headings); margin: calc(.5rem + 1em) 0 1rem; }
:where(.ds) h5, :where(.ds) .h5 { font-family: var(--font-display); font-weight: 600; font-size: 1.25rem; line-height: 1.15; color: var(--primary-headings); margin: calc(.5rem + 1em) 0 1rem; }
:where(.ds) h6, :where(.ds) .h6 { font-family: var(--font-sans); font-weight: 700; font-size: 1rem; line-height: 1.15; letter-spacing: .02em; text-transform: uppercase; color: var(--primary-headings); margin: calc(.5rem + 1em) 0 1rem; }
:where(.ds) p { margin: 0 0 var(--spacing-scale-2x); }
:where(.ds) a { color: var(--primary-interactive); }
:where(.ds) a:hover { color: var(--highlight-focus); text-decoration: underline; }
:where(.ds) small, :where(.ds) .small { font-size: .875em; }
:where(.ds) code, :where(.ds) .code { font-family: var(--font-mono); background: var(--neutral-background); padding: 0 .25em; }
:where(.ds) pre, :where(.ds) .pre { font-family: var(--font-mono); background: var(--neutral-background); padding: var(--spacing-scale-baseh) var(--spacing-scale-2x); margin: var(--spacing-scale-2x) 0; }
:where(.ds) mark { background: var(--warning-muted); color: inherit; }
:where(.ds) .lead { font-size: 1.25rem; }
:where(.ds) .label { font-weight: 700; color: var(--primary-headings); font-size: .875rem; }

/* Foco padrão do DS: highlight-focus */
.ds :focus-visible, .dis :focus-visible { outline: 2px solid var(--highlight-focus); outline-offset: 0; }

/* Grid: containers, linhas e colunas (12 colunas, gutter 24px) */
.container, .container-sm, .container-md, .container-lg, .container-xl, .container-fluid { width: 100%; margin: 0 auto; padding: 0 var(--spacing-scale-2x); }
@media (min-width: 576px) { .container, .container-sm { max-width: var(--container-sm-max); } }
@media (min-width: 992px) { .container, .container-sm, .container-md { max-width: var(--container-md-max); } }
@media (min-width: 1280px) { .container, .container-sm, .container-md, .container-lg { max-width: var(--container-lg-max); } }
@media (min-width: 1600px) { .container, .container-sm, .container-md, .container-lg, .container-xl { max-width: var(--container-xl-max); } }
.row { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); column-gap: var(--spacing-scale-3x); row-gap: var(--spacing-scale-3x); }
@media (min-width: 576px) { .row { grid-template-columns: repeat(8, minmax(0, 1fr)); } }
@media (min-width: 992px) { .row { grid-template-columns: repeat(12, minmax(0, 1fr)); } }
.col-1{grid-column:span 1}.col-2{grid-column:span 2}.col-3{grid-column:span 3}.col-4{grid-column:span 4}.col-5{grid-column:span 5}.col-6{grid-column:span 6}
.col-7{grid-column:span 7}.col-8{grid-column:span 8}.col-9{grid-column:span 9}.col-10{grid-column:span 10}.col-11{grid-column:span 11}.col-12{grid-column:1/-1}

.ds-icon { display: inline-block; flex: none; vertical-align: -0.125em; fill: currentColor; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* =====================================================================
   Button — btn--primary | secondary | tertiary, tom default | danger, circle
   ===================================================================== */
.btn { --c-area: var(--primary-interactive-area); --c-text: var(--primary-interactive); --c-dark: var(--primary-dark); --c-muted: var(--primary-muted); --c-tint: var(--blue-10);
  display: inline-flex; align-items: center; justify-content: center; gap: var(--spacing-scale-base); min-height: 2.5rem; padding: 0 1rem;
  font: inherit; font-size: 1rem; line-height: 1.2; font-weight: 400; white-space: nowrap; cursor: pointer; border-radius: 0; border: 1px solid transparent; background: transparent; color: var(--c-text); text-decoration: none; }
.btn--danger { --c-area: var(--danger-base); --c-text: var(--danger-base); --c-dark: var(--danger-dark); --c-muted: var(--danger-muted); --c-tint: var(--red-10); }
.btn--primary { background: var(--c-area); color: var(--white); border-color: var(--c-area); }
.btn--primary:hover { box-shadow: inset 0 0 0 2px var(--c-dark); }
.btn--primary:active { background: var(--c-dark); border-color: var(--c-dark); box-shadow: none; }
.btn--secondary { background: var(--white); border-color: var(--c-area); }
.btn--secondary:hover { box-shadow: inset 0 0 0 1px var(--c-area); }
.btn--secondary:active { background: var(--c-tint); }
.btn--tertiary:hover { border-color: var(--c-tint); }
.btn--tertiary:active { background: var(--c-tint); }
.btn:focus-visible { outline: 2px solid var(--highlight-focus); outline-offset: 0; box-shadow: none; }
.btn:disabled, .btn[aria-disabled="true"] { cursor: not-allowed; box-shadow: none; }
.btn--primary:disabled, .btn--primary[aria-disabled="true"] { background: var(--c-muted); border-color: var(--c-muted); }
.btn--secondary:disabled, .btn--secondary[aria-disabled="true"] { background: var(--white); border-color: var(--c-muted); color: var(--c-muted); }
.btn--tertiary:disabled, .btn--tertiary[aria-disabled="true"] { background: transparent; border-color: transparent; color: var(--c-muted); }
.btn--circle { width: 2.5rem; padding: 0; border-radius: var(--radius-pill); }
.btn.is-loading { pointer-events: none; }
.btn .ds-spin { animation: ds-spin .9s linear infinite; }
@keyframes ds-spin { to { transform: rotate(360deg); } }

/* =====================================================================
   Alert
   ===================================================================== */
.ds-alert { --a-border: var(--info-base); --a-bg: var(--primary-background); --a-title: var(--primary-dark);
  display: flex; gap: .75rem; align-items: flex-start; padding: 1rem 1.25rem; border: 2px solid var(--a-border); background: var(--a-bg); color: var(--neutral-body); }
.ds-alert--danger { --a-border: var(--danger-base); --a-bg: var(--danger-background); --a-title: var(--danger-dark); }
.ds-alert--success { --a-border: var(--success-base); --a-bg: var(--success-background); --a-title: var(--success-dark); }
.ds-alert--warning { --a-border: var(--warning-base); --a-bg: var(--warning-background); --a-title: var(--warning-dark); }
.ds-alert__icon { color: var(--a-border); line-height: 1.45; }
.ds-alert--warning .ds-alert__icon { color: var(--warning-dark); }
.ds-alert__content { flex: 1; min-width: 0; }
.ds-alert__title { margin: 0 0 .25rem; font-family: var(--font-display); font-weight: 600; font-size: 1.25rem; line-height: 1.3; color: var(--a-title); }
.ds-alert__body { margin: 0; font-size: .875rem; line-height: 1.45; }
.ds-alert--inline .ds-alert__body { font-size: .875rem; }
.ds-alert__close { border: 0; background: none; padding: 0; cursor: pointer; color: var(--neutral-muted); display: inline-flex; line-height: 1; }
.ds-alert__close:hover { color: var(--neutral-base); }

/* =====================================================================
   Accordion
   ===================================================================== */
.ds-accordion { border: 0; }
.ds-accordion__item { border-bottom: 1px solid var(--neutral-light); }
.ds-accordion__trigger { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .75rem 0; border: 0; background: none; cursor: pointer; text-align: left;
  font: inherit; font-weight: 700; font-size: 1rem; color: var(--primary-interactive); }
.ds-accordion__trigger .ds-icon { transition: transform .15s; }
.ds-accordion__trigger[aria-expanded="true"] .ds-icon { transform: rotate(180deg); }
.ds-accordion__panel { padding: 0 0 .75rem; font-size: 1rem; color: var(--neutral-body); }
.ds-accordion--sm .ds-accordion__trigger, .ds-accordion--sm .ds-accordion__panel { font-size: .875rem; }

/* =====================================================================
   Identificação de ambiente
   ===================================================================== */
.ds-env { position: relative; height: 3px; background: var(--env-color, var(--primary-interactive-area)); }
.ds-env--fixed { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; }
.ds-env__label { position: absolute; left: 0; top: 0; padding: 1px 22px 2px 20px; background: var(--env-color, var(--primary-interactive-area)); color: var(--white);
  font-size: 10px; line-height: 14px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%); }
.ds-env--homologacao { --env-color: var(--highlight-focus); }

/* =====================================================================
   Header (padrão mínimo)
   ===================================================================== */
.ds-header { display: flex; align-items: stretch; gap: 2rem; min-height: var(--spacing-scale-8x); padding: 0 var(--spacing-scale-5xh); background: var(--white); border-bottom: 1px solid var(--neutral-light); }
.ds-header__brand { display: flex; align-items: center; text-decoration: none; }
.ds-header__brand img { display: block; height: 38px; }
.ds-header__brand-text { font-family: var(--font-display); font-size: 1.5rem; line-height: 1; color: var(--primary-dark); font-weight: 800; }
.ds-header__brand-text span { font-weight: 600; }
.ds-header__nav { margin-left: auto; display: flex; }
.ds-header__nav ul { list-style: none; margin: 0; padding: 0; display: flex; gap: .5rem; align-items: stretch; }
.ds-header__nav li { display: flex; }
.ds-header__link { display: inline-flex; align-items: center; gap: .375rem; padding: 0 1rem; border: 0; background: none; cursor: pointer; font: inherit; font-size: .875rem;
  color: var(--neutral-body); text-decoration: none; border-bottom: 3px solid transparent; border-top: 3px solid transparent; }
.ds-header__link:hover { color: var(--primary-interactive); }
.ds-header__link[aria-current="page"] { font-weight: 700; color: var(--primary-headings); border-bottom-color: var(--primary-interactive-area); }
.ds-header__search { display: flex; align-items: center; }
.ds-header__user { display: flex; align-items: center; gap: .625rem; text-align: right; }
.ds-header__user-name { font-size: .875rem; line-height: 1.2; color: var(--neutral-body); }
.ds-header__user-role { display: block; font-size: 10px; letter-spacing: 1.2px; font-weight: 700; text-transform: uppercase; color: var(--neutral-base); }
.ds-avatar { position: relative; width: 28px; height: 28px; border-radius: var(--radius-pill); background: var(--badge-count); color: var(--white); display: inline-flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 700; flex: none; overflow: visible; }
.ds-avatar img { width: 100%; height: 100%; border-radius: inherit; object-fit: cover; }
.ds-avatar__dot { position: absolute; top: -2px; right: -2px; width: 9px; height: 9px; border-radius: 50%; background: var(--danger-base); border: 2px solid var(--white); }
.ds-header__login { color: var(--primary-interactive); font-size: .875rem; align-self: center; }

/* =====================================================================
   Footer
   ===================================================================== */
.ds-footer { display: flex; align-items: center; gap: 1.5rem; padding: .75rem var(--spacing-scale-5xh); border-top: 1px solid var(--neutral-light); background: var(--white); }
.ds-footer__brands { display: flex; align-items: center; gap: 1.5rem; }
.ds-footer__brands img { display: block; height: 26px; }
.ds-footer__signature { margin-left: auto; }
.ds-footer__signature img { display: block; height: 14px; }
.ds-footer__signature-text { font-size: .75rem; color: var(--neutral-dark); }
.ds-footer__signature-text b { font-style: italic; font-family: var(--font-display); font-weight: 800; font-size: 1rem; color: var(--primary-headings); }
.ds-footer--legacy { background: var(--neutral-background); border-top: 0; }

/* =====================================================================
   Formulários e dados (DIS)
   ===================================================================== */
.ds-field { display: flex; flex-direction: column; gap: 6px; }
.ds-field__label { font-size: .875rem; line-height: 1.43; font-weight: 700; color: var(--primary-headings); }
.ds-req { color: var(--danger-base); margin-left: 2px; }
.ds-field__row { display: flex; gap: 8px; align-items: center; }
.ds-input { height: var(--spacing-scale-5x); padding: 0 var(--spacing-scale-baseh); border: 1px solid var(--neutral-muted); border-radius: 0; background: var(--white);
  font: inherit; font-size: .875rem; color: var(--neutral-body); width: 100%; }
.ds-input::placeholder { color: var(--neutral-muted); }
.ds-search { display: flex; align-items: flex-end; gap: 1.5rem; }
.ds-search__field { flex: 1; display: flex; flex-direction: column; gap: 6px; }
.ds-search__label { font-size: 1rem; line-height: 1.5; font-weight: 700; color: var(--primary-headings); }
.ds-search__box { position: relative; }
.ds-search__box input { width: 100%; height: var(--spacing-scale-5x); border: 1px solid var(--neutral-muted); border-radius: 0; padding: 0 44px 0 12px; font: inherit; font-size: 1rem; color: var(--neutral-body); background: var(--white); }
.ds-search__box input::placeholder { color: var(--neutral-muted); }
.ds-search__box .ds-icon { position: absolute; right: 14px; top: 50%; transform: translateY(-50%); color: var(--primary-interactive-area); }

.ds-check { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-size: .875rem; color: var(--neutral-body); position: relative; }
.ds-check input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.ds-check__box { width: 14px; height: 14px; border: 1px solid var(--neutral-base); display: inline-flex; align-items: center; justify-content: center; background: var(--white); color: var(--white); flex: none; }
.ds-check input:checked + .ds-check__box { background: var(--primary-interactive-area); border-color: var(--primary-interactive-area); }
.ds-check input:focus-visible + .ds-check__box, .ds-check input:focus-visible + .ds-radio__dot { outline: 2px solid var(--highlight-focus); outline-offset: 1px; }
.ds-check--disabled { cursor: not-allowed; }
.ds-check--disabled .ds-check__box { border-color: var(--neutral-light); background: var(--neutral-background); }
.ds-radio__dot { width: 14px; height: 14px; border: 1px solid var(--neutral-base); border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; flex: none; background: var(--white); }
.ds-check input:checked + .ds-radio__dot { border-color: var(--primary-interactive-area); }
.ds-check input:checked + .ds-radio__dot::after { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--primary-interactive-area); }
.ds-radiogroup { display: flex; flex-direction: column; gap: 6px; border: 0; padding: 0; margin: 0; }
.ds-radiogroup legend { padding: 0; margin-bottom: 6px; }
.ds-radiogroup__opts { display: flex; gap: 16px; }

.ds-badge { display: inline-flex; align-items: center; height: 18px; padding: 0 8px; border-radius: var(--radius-pill); color: var(--white);
  font-size: 10px; line-height: 14px; font-weight: 700; letter-spacing: .8px; text-transform: uppercase; white-space: nowrap; }
.ds-badge--success { background: var(--success-base); }
.ds-badge--danger { background: var(--danger-base); }
.ds-badge--neutral { background: var(--neutral-base); }
.ds-count { display: inline-flex; align-items: center; justify-content: center; min-width: 18px; height: 16px; padding: 0 5px; border-radius: var(--radius-pill);
  background: var(--badge-count); color: var(--white); font-size: 10px; line-height: 14px; font-weight: 700; }

.ds-card { border: 1px solid var(--neutral-light); background: var(--white); }
.ds-card__head { display: flex; align-items: center; gap: 10px; padding: 18px 16px; }
.ds-card__title { margin: 0; font-family: var(--font-display); font-size: 1.25rem; line-height: 1.4; font-weight: 600; color: var(--primary-headings); }
.ds-card__toggle { margin-left: auto; }
.ds-card__body { padding: 0 16px 16px; }
.ds-card__foot { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-top: 12px; }
.ds-iconbtn { border: 0; background: none; cursor: pointer; color: var(--primary-interactive-area); padding: 4px; display: inline-flex; }
.ds-linkbtn { display: inline-flex; align-items: center; gap: 4px; border: 0; background: none; padding: 0; cursor: pointer;
  font-size: 10px; line-height: 14px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--primary-interactive); }

.ds-table { width: 100%; border-collapse: collapse; font-size: 14px; line-height: 20px; }
.ds-table th { text-align: left; padding: 12px 16px; border-bottom: 1px solid var(--neutral-light); white-space: nowrap;
  font-size: 10px; line-height: 12px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--neutral-body); vertical-align: middle; }
.ds-table th.ds-th--wrap { white-space: normal; }
.ds-th__inner { display: inline-flex; align-items: center; gap: 6px; }
.ds-th__sort { border: 0; background: none; padding: 0; cursor: pointer; color: var(--primary-interactive-area); display: inline-flex; }
.ds-table td { padding: 12px 16px; border-bottom: 1px solid var(--neutral-light); color: var(--neutral-body); vertical-align: middle; }
.ds-table tbody tr:hover td { background: var(--neutral-background); }
.ds-table .ds-td--check { width: 40px; padding-right: 0; }
.ds-table--compact td, .ds-table--compact th { padding: 10px 12px; font-size: 13px; }
.ds-table--compact th { font-size: 9px; }
.ds-table td.ds-td--group { border-bottom-color: transparent; }
.ds-td--sub { color: var(--neutral-base); font-size: 12px; line-height: 16px; display: block; }
.ds-medlink { display: inline-flex; align-items: center; gap: 4px; color: var(--primary-interactive-area); text-decoration: none; background: none; border: 0; padding: 0; font: inherit; cursor: pointer; text-align: left; }
.ds-medlink:hover { color: var(--highlight-focus); text-decoration: underline; }
.ds-medlink--disabled { color: var(--neutral-muted); }
.ds-prog { color: var(--neutral-base); margin-left: 4px; }
.ds-warn { display: flex; align-items: center; gap: 4px; color: var(--danger-base); font-size: 12px; font-weight: 700; }

.ds-pagination { display: flex; align-items: center; justify-content: space-between; padding: 24px 16px; color: var(--neutral-dark); font-size: 14px; }
.ds-pagination b { font-weight: 400; color: var(--neutral-body); }
.ds-pagination__right { display: flex; align-items: center; gap: 28px; }
.ds-pagination__group { display: inline-flex; align-items: center; gap: 8px; color: var(--neutral-body); }
.ds-pagination .ds-icon { color: var(--primary-interactive-area); }

.ds-info { display: grid; grid-template-columns: repeat(var(--cols, 4), minmax(0, 1fr)); column-gap: var(--spacing-scale-3x); row-gap: 20px; }
.ds-info__label { font-size: 14px; line-height: 20px; font-weight: 700; color: var(--primary-headings); margin-bottom: 10px; }
.ds-info__value { font-size: 14px; line-height: 20px; color: var(--neutral-body); }
.ds-subhead { margin: 20px 0 12px; font-size: 14px; line-height: 20px; font-weight: 800; letter-spacing: 0.5px; text-transform: uppercase; color: var(--primary-headings); }

/* ---------- DIS: shell, paciente, menu, item de dispensação ---------- */
.dis-overline, .dis-breadcrumb { font-size: 10px; line-height: 14px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--primary-interactive); }
.dis-breadcrumb { display: flex; align-items: center; gap: 8px; list-style: none; margin: 0; padding: 0; }
.dis-breadcrumb a { color: inherit; text-decoration: none; }
.dis-breadcrumb .ds-icon { color: var(--neutral-muted); }
.dis-patient { padding: 24px var(--spacing-scale-5xh) 20px; border-bottom: 1px solid var(--neutral-light); }
.dis-patient__name { margin: 2px 0 6px; font-family: var(--font-display); font-size: 2.5rem; line-height: 1.15; font-weight: 800; color: var(--primary-surfaces); }
.dis-patient__meta { display: flex; flex-wrap: wrap; align-items: center; row-gap: 6px; font-size: 14px; line-height: 20px; }
.dis-patient__item { color: var(--neutral-dark); }
.dis-patient__item b { font-weight: 400; color: var(--neutral-body); }
.dis-patient__sep { color: var(--neutral-muted); margin: 0 12px; }
.dis-patient__more { margin-left: 20px; }
.dis-patient__details { margin-top: 8px; }
.dis-shell { min-height: 100%; display: flex; flex-direction: column; }
.dis-shell__body { flex: 1; display: flex; align-items: stretch; padding: 16px var(--spacing-scale-5xh) 0; }
.dis-shell__content { flex: 1; min-width: 0; padding: 4px 0 40px 20px; }
.dis-sidenav { width: var(--sidebar-width); flex: none; display: flex; flex-direction: column; border-right: 2px solid var(--neutral-light); padding: 8px 16px 0 0; min-height: 600px; }
.dis-sidenav--collapsed { width: 56px; }
.dis-sidenav__list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.dis-sidenav__item { width: 100%; display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 4px; border: 0; background: none; cursor: pointer;
  font-size: 1rem; line-height: 1.5; color: var(--primary-interactive); text-align: left; white-space: nowrap; }
.dis-sidenav__item:hover { background: var(--neutral-background); }
.dis-sidenav__item .ds-icon { color: var(--neutral-base); width: 16px; }
.dis-sidenav__item--active { font-weight: 700; color: var(--primary-interactive-area); }
.dis-sidenav__item--active .ds-icon { color: var(--primary-interactive-area); }
.dis-sidenav__foot { margin-top: auto; border-top: 2px solid var(--neutral-light); padding: 12px 0; display: flex; justify-content: flex-end; }
.dis-sidenav--collapsed .dis-sidenav__foot { justify-content: center; }
.dis-item { padding: 0 0 24px; border-bottom: 1px solid var(--neutral-light); margin-bottom: 20px; }
.dis-item__title { display: flex; align-items: center; gap: 8px; margin: 0 0 4px; font-size: 1rem; line-height: 1.5; font-weight: 700; color: var(--primary-headings); }
.dis-item__program { display: inline-flex; align-items: center; gap: 6px; color: var(--primary-interactive); font-size: 14px; font-weight: 700; text-decoration: none; margin: 0 0 4px; }
.dis-item__top { margin-top: 16px; }
.dis-item__history { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); column-gap: var(--spacing-scale-3x); margin-top: 24px; }
.dis-item__history-col { grid-column: span 2; }
.dis-histlist { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--spacing-scale-3x); }
.dis-hist { font-size: 14px; color: var(--neutral-body); }
.dis-hist__date { font-size: 12px; color: var(--neutral-base); margin-bottom: 2px; }
.dis-item__history .ds-accordion__item { border-bottom: 0; }
.dis-item__history .ds-accordion__trigger { justify-content: flex-start; font-size: 14px; color: var(--primary-headings); padding: 0 0 12px; }
.dis-item__history .ds-accordion__trigger .ds-icon { color: var(--primary-interactive-area); }
.dis-notes .ds-accordion__trigger { font-size: 14px; color: var(--primary-headings); padding: 10px 0; }
.dis-notes .ds-accordion__trigger .ds-icon { color: var(--primary-interactive-area); }
.dis-notes .ds-accordion__panel { font-size: 13px; line-height: 18px; }
.dis-notes__src { display: block; margin-top: 6px; font-size: 12px; color: var(--neutral-base); }
.dis-stack { display: flex; flex-direction: column; gap: var(--spacing-scale-3x); }
.dis-grid-2 { display: grid; grid-template-columns: 2fr 1fr; gap: var(--spacing-scale-3x); align-items: start; }
.dis-section-title { margin: 0 0 16px; font-family: var(--font-display); font-size: 1.25rem; line-height: 1.4; font-weight: 600; color: var(--primary-headings); }
.dis-page-title { margin: 0 0 20px; font-family: var(--font-display); font-size: 1.5rem; line-height: 1.3; font-weight: 600; color: var(--primary-headings); }
.dis-actions { display: flex; justify-content: space-between; align-items: center; margin-top: 24px; }
.dis-hr { border: 0; border-top: 1px solid var(--neutral-light); margin: 24px 0; }

/* ---------- Formulários: campos com ícone, data, seleção, texto longo ---------- */
.ds-input-wrap { position: relative; display: block; }
.ds-input-wrap .ds-input { padding-right: 40px; }
.ds-input-wrap > .ds-icon { position: absolute; right: 14px; top: 50%; transform: translateY(-50%); color: var(--primary-interactive-area); pointer-events: none; }
.ds-input-wrap.is-disabled > .ds-icon { color: var(--neutral-muted); }
.ds-input:disabled, .ds-input[readonly] { background: var(--neutral-background); color: var(--neutral-dark); cursor: not-allowed; }
.ds-field__label.is-disabled { color: var(--neutral-dark); font-weight: 700; }
.ds-field__hint { font-size: 12px; line-height: 16px; color: var(--neutral-dark); }
.ds-select { appearance: none; -webkit-appearance: none; cursor: pointer; }
.ds-select:invalid, .ds-select option[value=""] { color: var(--neutral-dark); }
.ds-textarea { height: auto; min-height: 56px; padding: 8px var(--spacing-scale-baseh); resize: vertical; line-height: 20px; }
.ds-badge--warning { background: var(--highlight-dark); }
.ds-check--inline { font-size: 13px; }

/* ---------- Modal ---------- */
.ds-modal__backdrop { position: fixed; inset: 0; z-index: 1000; display: flex; align-items: center; justify-content: center; background: rgba(0, 24, 90, .68); padding: 16px; }
.ds-modal { background: var(--white); width: 520px; max-width: 100%; max-height: 100%; overflow: auto; padding: 32px; box-shadow: 0 8px 24px rgba(0, 0, 0, .25); font-family: var(--font-sans); color: var(--neutral-body); }
.ds-modal__title { margin: 0 0 16px; font-family: var(--font-display); font-size: 1.25rem; line-height: 1.4; font-weight: 600; color: var(--primary-headings); }
.ds-modal__body { display: flex; flex-direction: column; gap: 20px; font-size: 14px; line-height: 20px; }
.ds-modal__body > p { margin: 0; }
.ds-modal__actions { display: flex; justify-content: flex-end; align-items: center; gap: 16px; margin-top: 32px; }

/* ---------- Programas de Saúde ---------- */
.dis-prog { padding: 4px 0; }
.dis-prog__head { margin: 0; display: flex; align-items: center; gap: 10px; padding: 8px 0; font-size: 14px; line-height: 20px; }
.dis-prog__toggle { display: inline-flex; align-items: center; gap: 8px; border: 0; background: none; padding: 0; cursor: pointer; color: var(--primary-interactive); font: inherit; font-weight: 800; letter-spacing: 1.2px; text-transform: uppercase; }
.dis-prog__toggle:hover .dis-prog__name { color: var(--highlight-dark); }
.dis-prog__warn { color: var(--danger-base); font-size: 13px; }
.dis-prog__sub { padding: 4px 0 8px 20px; font-size: 14px; color: var(--neutral-body); }
.dis-prog__sub small { margin-left: 8px; font-size: 12px; color: var(--neutral-base); }
.dis-prog__body { padding: 12px 0 8px; }

/* ---------- Anotações ---------- */
.dis-note { display: flex; justify-content: space-between; align-items: flex-start; gap: 24px; padding: 20px 0; border-bottom: 1px solid var(--neutral-light); }
.dis-note__main { display: flex; flex-direction: column; gap: 8px; min-width: 0; align-items: flex-start; }
.dis-note__head { display: flex; align-items: center; gap: 12px; }
.dis-note__date { margin: 0; font-family: var(--font-display); font-size: 1rem; line-height: 1.4; font-weight: 600; color: var(--primary-headings); }
.dis-note__prazo { font-size: 12px; font-weight: 700; color: var(--neutral-base); }
.dis-note__text { margin: 0; font-size: 14px; line-height: 20px; color: var(--neutral-body); }
.dis-note__src { font-size: 12px; line-height: 16px; color: var(--neutral-base); }
.dis-note__src b { color: var(--neutral-base); }
.dis-form { display: flex; flex-direction: column; gap: 20px; }
.dis-form-row { display: flex; gap: 24px; align-items: flex-end; }
.dis-note-form { margin: 24px 0 8px; padding: 24px 0 8px; border-top: 1px solid var(--neutral-light); }

/* ---------- Header estilo DIS: menu ao lado da marca, usuário à direita ---------- */
.ds-header { gap: 1.5rem; }
.ds-header__nav { margin-left: 0; margin-right: auto; }
.ds-header__nav ul { gap: .25rem; }
.ds-header__item { position: relative; display: flex; }
.ds-header__link { font-size: 11px; line-height: 16px; font-weight: 700; letter-spacing: 1.2px; text-transform: uppercase; color: var(--primary-interactive); border-bottom: 3px solid transparent; }
.ds-header__link[aria-current="page"] { color: var(--primary-interactive-area); border-bottom-color: var(--primary-interactive-area); }
.ds-header__link.has-sub { border-bottom-color: var(--neutral-light); }
.ds-header__link.has-sub.is-open { border-bottom-color: var(--primary-interactive-area); }
.ds-header__user-name { font-size: .8125rem; color: var(--neutral-base); }
.ds-header .ds-avatar { background: none; color: var(--primary-interactive-area); width: auto; height: auto; }
.ds-header__sub { position: absolute; top: 100%; left: 0; z-index: 50; list-style: none; margin: 0; padding: 8px 0; min-width: 240px; background: var(--white); border: 1px solid var(--neutral-light); box-shadow: 0 6px 16px rgba(0, 0, 0, .18); }
.ds-header__subitem { display: block; width: 100%; text-align: left; border: 0; background: none; cursor: pointer; padding: 10px 20px; font: inherit; font-size: 14px; line-height: 20px; color: var(--neutral-body); }
.ds-header__subitem:hover, .ds-header__subitem:focus-visible { background: var(--neutral-background); color: var(--primary-interactive); }
.ds-header__nav ul.ds-header__sub { display: block; gap: 0; }
.ds-header__nav ul.ds-header__sub li { display: block; }
.ds-header__subitem { white-space: nowrap; }

/* SideNav fixo: ocupa a altura visível ao rolar; botão de recolher sempre embaixo */
.dis-sidenav { min-height: 0; padding: 0 16px 0 0; }
.dis-sidenav__sticky { position: sticky; top: 0; display: flex; flex-direction: column; min-height: 320px; padding-top: 8px; box-sizing: border-box; }

/* ---------- Estados de campo: sucesso (verde) e erro (vermelho) ---------- */
.ds-field--success .ds-field__label { color: var(--success-dark); }
.ds-field--success .ds-input { border-color: var(--success-dark); box-shadow: 0 0 0 1px var(--success-dark); }
.ds-field--danger .ds-field__label { color: var(--danger-dark); }
.ds-field--danger .ds-input, .ds-input--danger { border-color: var(--danger-base); box-shadow: 0 0 0 1px var(--danger-base); }
.ds-field--danger .ds-field__hint, .ds-field__hint--danger { display: flex; align-items: center; gap: 4px; color: var(--danger-dark); font-weight: 600; margin-top: 4px; }

/* ---------- AutocompleteField ---------- */
.ds-ac__box { position: relative; }
.ds-ac__panel { position: absolute; z-index: 30; top: 100%; left: 0; right: 0; background: var(--white); box-shadow: 0 4px 10px rgba(0,0,0,.2); padding: 0 8px 8px; }
.ds-ac__count { padding: 14px 8px 10px; font-size: 12px; line-height: 16px; color: var(--neutral-dark); border-bottom: 2px solid var(--neutral-light); }
.ds-ac__list { list-style: none; margin: 0; padding: 4px 0 0; max-height: 360px; overflow-y: auto; }
.ds-ac__opt { padding: 9px 8px; font-size: .9375rem; line-height: 21px; color: var(--neutral-body); cursor: pointer; }
.ds-ac__opt b { font-weight: 700; color: var(--primary-headings); }
.ds-ac__opt.is-active { background: var(--primary-background); }

/* ---------- DispensationCalc ---------- */
.dis-calc__suffix { margin-left: 8px; font-size: 14px; color: var(--neutral-body); }
.dis-calc .ds-info__value .ds-input { width: 100%; }
.dis-calc .ds-info__value .ds-input[style*="width"] { width: 96px; }
.dis-calc .ds-radiogroup__opts { display: flex; gap: 12px; flex-wrap: wrap; }
.dis-calc__plan { margin-top: 20px; }
.dis-calc__plan-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); column-gap: var(--spacing-scale-3x); row-gap: 12px; }
.dis-calc .ds-subhead { margin-top: 32px; }

/* MedicationList: medicamentos incluídos na prescrição */
.dis-medlist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.dis-medlist__item { padding: 8px 0; border-bottom: 1px solid var(--neutral-light); }
.dis-medlist__row { display: flex; align-items: center; gap: 8px 12px; flex-wrap: wrap; min-width: 0; }
.dis-medlist__name { font-size: 14px; text-align: left; }
.dis-medlist__meta { font-size: 12px; color: var(--neutral-dark); flex: 1 1 220px; min-width: 0; overflow-wrap: anywhere; }
.dis-medlist__item.is-off .dis-medlist__name, .dis-medlist__item.is-off .dis-medlist__meta { color: var(--neutral-base); text-decoration: line-through; }
.dis-medlist__plan { margin: 8px 0 4px 28px; }
.dis-medlist__name { text-transform: none; font-weight: 400; letter-spacing: 0; }

/* =====================================================================
   Responsivo (tablet e mobile)
   Tudo por container query, nunca por largura da janela: o layout reage ao
   espaço que o shell recebe (vale para páginas, iframes e pré-visualizações).
   - dis-shell: container do AppShell. Tablet até 1024px, mobile até 640px.
   - dis: container do conteúdo (<main>). Abaixo de 720px as tabelas viram lista.
   ===================================================================== */
.dis-shell { container: dis-shell / inline-size; }
.dis-shell__content { container: dis / inline-size; }
.ds-header { position: relative; }
.ds-header__burger, .dis-mobhead, .ds-chevbtn, .ds-header__scrim, .ds-header__drawer-foot { display: none; }
.ds-header__account { display: contents; }
.ds-medlink__chev { display: inline-flex; margin-left: 4px; }
.dis-mobback { font-size: 12px; letter-spacing: 1.2px; padding: 0; }
.dis-mobtitle { margin: 8px 0 4px; font-family: var(--font-display); font-size: 1.75rem; line-height: 1.2; font-weight: 600; color: var(--primary-interactive); }

/* Tablet */
@container dis-shell (max-width: 1024px) {
  .ds-header { padding: 0 24px; gap: 1rem; }
  .ds-header__brand img { height: 32px; }
  .ds-header__user-name { max-width: 110px; }
  .dis-patient { padding: 20px 24px 16px; }
  .dis-patient__name { font-size: 2rem; }
  .dis-shell__body { padding: 16px 24px 0; }
  .dis-shell__content { padding-left: 16px; }
  .dis-grid-2 { grid-template-columns: 1fr; }
  .ds-footer { padding: .75rem 24px; }
  .ds-table { display: block; overflow-x: auto; }
  .ds-table td, .ds-table th { white-space: nowrap; }
  .ds-table td.ds-td--check + td, .ds-table tr:not(:has(.ds-td--check)) td:first-child { white-space: normal; min-width: 170px; }
}

/* Mobile */
@container dis-shell (max-width: 640px) {
  .ds-header { padding: 0 16px; min-height: 56px; gap: .75rem; flex-wrap: wrap; align-items: center; }
  .ds-header__brand { flex: 1; min-width: 0; }
  .ds-header__brand img { height: 28px; max-width: 100%; object-fit: contain; object-position: left; }
  .ds-header__burger { display: inline-flex; position: absolute; top: 8px; right: 12px; z-index: 30; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1px solid var(--neutral-light); border-radius: var(--radius-pill); background: var(--white); color: var(--primary-interactive); cursor: pointer; }
  .ds-header__nav, .ds-header__user { display: none; }
  /* Menu aberto: gaveta à direita com fundo escurecido */
  .ds-header--open .ds-header__scrim { display: block; position: fixed; inset: 0; background: rgba(0, 24, 90, .45); z-index: 900; }
  .ds-header--open .ds-header__burger { position: fixed; z-index: 960; border-color: transparent; background: none; }
  .ds-header--open .ds-header__nav { display: block; position: fixed; top: 0; right: 0; bottom: 0; width: min(82%, 320px); margin: 0; padding: 64px 0 190px; overflow-y: auto; background: var(--white); z-index: 950; box-shadow: -4px 0 16px rgba(0, 0, 0, .18); }
  .ds-header--open .ds-header__nav ul { flex-direction: column; gap: 0; }
  .ds-header--open .ds-header__item { flex-direction: column; }
  .ds-header--open .ds-header__link { width: 100%; justify-content: space-between; padding: 14px 20px; border: 0; border-left: 3px solid transparent; }
  .ds-header--open .ds-header__link[aria-current="page"], .ds-header--open .ds-header__link.is-open { border-left-color: var(--primary-interactive-area); }
  .ds-header--open .ds-header__sub { position: static; box-shadow: none; border: 0; min-width: 0; padding: 0; }
  .ds-header--open .ds-header__subitem { white-space: normal; padding: 10px 20px 10px 23px; color: var(--neutral-dark); }
  .ds-header--open .ds-header__subitem:hover, .ds-header--open .ds-header__subitem:focus-visible, .ds-header--open .ds-header__subitem:active { color: var(--primary-interactive); background: var(--primary-background); }
  .ds-header--open .ds-header__account { display: block; position: fixed; right: 0; bottom: 0; width: min(82%, 320px); padding: 16px 20px 20px; background: var(--white); z-index: 951; }
  .ds-header--open .ds-header__user { display: flex; flex-direction: column; align-items: flex-start; text-align: left; }
  .ds-header--open .ds-header__user-name { font-size: 1rem; font-weight: 700; color: var(--primary-headings); max-width: none; }
  .ds-header--open .ds-header__user-role { display: inline-block; margin-top: 6px; padding: 2px 10px; border-radius: var(--radius-pill); background: var(--danger-base); color: var(--white); font-size: 11px; letter-spacing: .4px; text-transform: none; }
  .ds-header--open .ds-header__user .ds-avatar { display: none; }
  .ds-header--open .ds-header__drawer-foot { display: flex; flex-direction: column; align-items: flex-start; gap: 12px; margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--neutral-light); }

  .dis-patient { padding: 16px; }
  .dis-patient__name { font-size: 1.5rem; margin-bottom: 8px; }
  .dis-patient__meta { flex-direction: column; align-items: flex-start; row-gap: 2px; }
  .dis-patient__sep { display: none; }
  .dis-patient__more { margin-left: 0; margin-top: 6px; }

  .dis-shell__body { flex-direction: column; padding: 0; }
  .dis-shell__content { padding: 16px 16px 32px; }
  .dis-sidenav { display: none; width: auto; border-right: 0; padding: 0 16px; }
  .dis-sidenav--collapsed { width: auto; }
  .dis-sidenav__sticky { position: static; height: auto !important; min-height: 0; }
  .dis-sidenav__foot { display: none; }
  .dis-sidenav--collapsed .dis-sidenav__item { font-size: 0; }

  /* Navegação mobile: data-view="menu" mostra a lista de seções; data-view="section" mostra a seção com SectionBar */
  .dis-shell[data-view="menu"] .dis-shell__content { display: none; }
  .dis-shell[data-view="menu"] .dis-sidenav { display: block; }
  .dis-shell[data-view="menu"] .dis-sidenav__item { height: 52px; border-bottom: 1px solid var(--neutral-light); font-size: 15px; }
  .dis-shell[data-view="menu"] .dis-sidenav__list { gap: 0; }
  .dis-shell[data-view="section"] .dis-patient { display: none; }
  .dis-shell[data-view="section"] .dis-mobhead { display: block; padding: 12px 16px 0; }

  .dis-page-title { font-size: 1.25rem; }
  .dis-grid-2, .dis-stack { gap: 16px; }
  .dis-form-row { flex-direction: column; align-items: stretch; gap: 12px; }
  .dis-actions { flex-direction: column-reverse; align-items: stretch; gap: 12px; }
  .dis-actions .btn, .dis-form-row .btn { width: 100%; justify-content: center; }
  .ds-field { max-width: 100%; }
  .ds-field .ds-input, .ds-field .ds-input-wrap { max-width: 100%; }
  .ds-input-wrap .ds-input { width: 100% !important; }
  .ds-field__row { flex-wrap: wrap; }
  .ds-field__row .btn { width: 100%; justify-content: center; }
  .ds-field__row > .ds-input, .ds-field__row > .ds-input-wrap { flex: 1 1 100%; width: 100% !important; max-width: 100%; }
  .ds-footer { flex-direction: column; align-items: flex-start; gap: 12px; padding: 12px 16px; }
  .ds-footer__signature { margin-left: 0; }
  .dis-prog__head { flex-wrap: wrap; gap: 8px 10px; align-items: center; }
  .dis-prog__toggle { flex: 1 1 100%; text-align: left; justify-content: flex-start; letter-spacing: .8px; font-size: 12px; line-height: 1.4; }
  .dis-prog__sub { padding-left: 0; }
  .dis-next { grid-template-columns: 1fr !important; gap: 16px !important; }
}

/* Listas em cartões (tablet com menu aberto e mobile) */
@container dis (max-width: 719px) {
  .ds-table, .ds-table tbody { display: block; overflow: visible; width: 100%; }
  .ds-table thead { display: none; }
  .ds-table tbody tr { display: grid; grid-template-columns: 28px minmax(0, 1fr); column-gap: 8px; padding: 12px 4px; border-bottom: 1px solid var(--neutral-light); }
  .ds-table tbody tr:hover td { background: none; }
  .ds-table td { display: block; padding: 2px 0; border: 0; grid-column: 2; white-space: normal !important; min-width: 0 !important; overflow-wrap: anywhere; }
  .ds-table td:empty { display: none; }
  .ds-table td.ds-td--check { grid-column: 1; grid-row: 1 / span 8; padding: 0; width: auto; }
  .ds-table tr:not(:has(.ds-td--check)) { grid-template-columns: minmax(0, 1fr); }
  .ds-table tr:not(:has(.ds-td--check)) td { grid-column: 1; }
  .ds-table td[data-label]::before { content: attr(data-label) ": "; font-size: 11px; letter-spacing: .6px; text-transform: uppercase; font-weight: 700; color: var(--neutral-dark); }
  .ds-table td[data-label]:first-of-type::before { display: none; }

  /* Papéis das colunas (DataTable: card="title" | "status" | "caption" | "inline") */
  .ds-table td[data-role="title"]::before, .ds-table td[data-role="status"]::before { display: none; }
  .ds-table td[data-role="caption"] { order: -1; font-size: 12px; }
  .ds-table td[data-role="caption"][data-card-label]::before { content: attr(data-card-label) " "; text-transform: none; letter-spacing: 0; font-weight: 400; font-size: 12px; color: inherit; }
  .ds-table td[data-role="status"] { order: 5; padding-top: 6px; }
  .ds-table td[data-role="inline"] * { display: inline !important; }
  .ds-table td[data-role="inline"] { white-space: nowrap !important; font-size: 12px; }
  .ds-table td[data-role="inline"]::before { font-size: 10px; }
  .ds-table td[data-role="inline"] .ds-td--sub { font-size: 12px; }
  .ds-table td[data-role="inline"] .ds-td--sub::before { content: " · "; }

  /* Item fechado: legenda no topo; nome, situação e chevron na mesma linha */
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) { grid-template-columns: minmax(0, 1fr) auto 28px; align-items: center; }
  .ds-table tr:has(td.ds-td--check):has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) { grid-template-columns: 28px minmax(0, 1fr) auto 28px; }
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) td[data-label]:not([data-role="title"]):not([data-role="status"]):not([data-role="caption"]) { display: none; }
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) td[data-role="title"] { display: contents; }
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) td[data-role="caption"] { grid-column: 1 / -1; }
  .ds-table tr:has(td.ds-td--check):has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) td[data-role="caption"] { grid-column: 2 / -1; }
  .ds-table tr:has(td.ds-td--check):has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) td.ds-td--check { grid-row: 1 / span 2; }
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) td[data-role="status"] { grid-column: auto; order: 2; padding: 0 4px 0 8px; justify-self: end; }
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) .ds-medlink { order: 1; grid-column: auto; justify-self: start; text-align: left; padding: 4px 0; }
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) .ds-chevbtn { display: inline-flex; order: 3; grid-column: auto; justify-self: end; }
  .ds-table tr:has(td[data-role="title"]:not(:empty)):has(td[data-role="status"]) .ds-medlink__chev { display: none; }
  /* Item aberto (linhas de detalhe, título vazio): "Situação: [badge]" */
  .ds-table tr:has(td[data-role="title"]:empty) td[data-role="status"] { display: flex; align-items: center; gap: 6px; padding-top: 6px; }
  .ds-table tr:has(td[data-role="title"]:empty) td[data-role="status"]::before { display: inline; }
  .ds-table tr:has(td[data-role="title"]:empty) td[data-role="caption"] { display: none; }

  .ds-info { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; row-gap: 14px; }
  .ds-info__label, .ds-info__value { overflow-wrap: anywhere; }
  .ds-pagination { flex-direction: column; align-items: flex-start; gap: 12px; padding: 16px 4px; }
  .ds-pagination__right { flex-wrap: wrap; gap: 8px 20px; }
  .ds-pagination__group { white-space: nowrap; }
}

/* ---------------- IncludedMedicationList / DispensedMedicationList ---------------- */
.dis-medtable { margin: 0; }
.dis-medtable .dis-section-title { margin: 0 0 8px; }
.dis-medtable__empty { margin: 0; padding: 16px 0; font-size: 14px; color: var(--neutral-dark); }
.dis-medtable .ds-table td:last-child { text-align: right; white-space: nowrap; }
@container dis (max-width: 719px) {
  .dis-medtable .ds-table td:last-child { text-align: left; padding-top: 4px; }
  .dis-medtable .ds-table td[data-role="inline"] { display: block; white-space: normal !important; }
  .dis-medtable .ds-table td[data-role="inline"] * { display: inline !important; }
  .dis-medtable .ds-table td[data-role="inline"]::before { content: attr(data-label) ": "; font-size: 10px; }
}

/* Layout: cabeçalho fixo, menu lateral por grupo, conteúdo em coluna única com exemplo vivo e abas de código. */
:root {
  --dx-bg: #ffffff;
  --dx-surface: #f5f7fb;
  --dx-fg: #14213d;
  --dx-muted: #55627d;
  --dx-line: #dde3ef;
  --dx-accent: #2f4ec2;
  --dx-accent-fg: #ffffff;
  --dx-accent-soft: #e8edfc;
  --dx-code-bg: #0f1a33;
  --dx-code-fg: #dbe4ff;
  --dx-code-line: #25335a;
  --dx-tok-com: #7f8fb8;
  --dx-tok-str: #9be3b0;
  --dx-tok-kw: #ffb38a;
  --dx-tok-tag: #8fb4ff;
  --dx-tok-attr: #f2d98d;
  --dx-tok-num: #f2a6d8;
  --dx-ok: #1f7a43;
  --dx-warn-bg: #fff4e5;
  --dx-warn-line: #f0b36a;
  --dx-font: "Noto Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --dx-display: "Noto Sans Display", "Noto Sans", system-ui, sans-serif;
  --dx-mono: "Noto Sans Mono", ui-monospace, "SFMono-Regular", Menlo, monospace;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --dx-bg: #0e1424; --dx-surface: #151d33; --dx-fg: #e6ebf8; --dx-muted: #9aa8c9; --dx-line: #27314d;
    --dx-accent: #8fb0ff; --dx-accent-fg: #0e1424; --dx-accent-soft: #1c2848;
    --dx-code-bg: #0a1022; --dx-code-fg: #dbe4ff; --dx-code-line: #1f2a4a;
    --dx-ok: #6fd69a; --dx-warn-bg: #2b2111; --dx-warn-line: #8a6420;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --dx-bg: #0e1424; --dx-surface: #151d33; --dx-fg: #e6ebf8; --dx-muted: #9aa8c9; --dx-line: #27314d;
  --dx-accent: #8fb0ff; --dx-accent-fg: #0e1424; --dx-accent-soft: #1c2848;
  --dx-code-bg: #0a1022; --dx-code-fg: #dbe4ff; --dx-code-line: #1f2a4a;
  --dx-ok: #6fd69a; --dx-warn-bg: #2b2111; --dx-warn-line: #8a6420;
  color-scheme: dark;
}
html { scroll-padding-top: 72px; }
body { background: var(--dx-bg); color: var(--dx-fg); font-family: var(--dx-font); font-size: 15px; line-height: 1.6; }
* { box-sizing: border-box; }
a { color: var(--dx-accent); }
:focus-visible { outline: 2px solid #ff7f50; outline-offset: 2px; }
button { font: inherit; color: inherit; }
code { font-family: var(--dx-mono); font-size: .86em; background: var(--dx-surface); border: 1px solid var(--dx-line); padding: 1px 5px; }

/* topbar */
.dx-top { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 30; display: flex; align-items: center; gap: 16px; height: 56px; padding-inline: 16px; background: var(--dx-bg); border-bottom: 1px solid var(--dx-line); }
.dx-brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--dx-fg); min-width: 0; }
.dx-brand img { height: 30px; display: block; }
.dx-brand b { font-family: var(--dx-display); font-weight: 800; font-size: 15px; white-space: nowrap; }
.dx-ver { font-family: var(--dx-mono); font-size: 11px; color: var(--dx-muted); border: 1px solid var(--dx-line); padding: 1px 7px; white-space: nowrap; }
.dx-top__sp { flex: 1; }
.dx-stacks { display: flex; gap: 6px; font-size: 12px; color: var(--dx-muted); }
.dx-stacks span { border: 1px solid var(--dx-line); padding: 1px 8px; white-space: nowrap; }
.dx-iconbtn { border: 1px solid var(--dx-line); background: var(--dx-bg); width: 36px; height: 36px; cursor: pointer; display: inline-grid; place-items: center; }
.dx-iconbtn:hover { border-color: var(--dx-accent); color: var(--dx-accent); }
.dx-menu-btn { display: none; }

/* shell */
.dx-shell { display: grid; grid-template-columns: 272px minmax(0, 1fr); align-items: start; }
.dx-side { position: sticky; top: calc(56px + env(safe-area-inset-top, 0px)); height: calc(100vh - 56px - env(safe-area-inset-top, 0px)); overflow-y: auto; border-right: 1px solid var(--dx-line); padding: 16px 12px 40px 16px; background: var(--dx-bg); }
.dx-search { width: 100%; height: 38px; border: 1px solid var(--dx-line); background: var(--dx-surface); color: var(--dx-fg); padding: 0 12px; font: inherit; font-size: 14px; }
.dx-search::placeholder { color: var(--dx-muted); }
.dx-nav { margin-top: 12px; display: flex; flex-direction: column; gap: 18px; }
.dx-nav h2 { margin: 0 0 4px; font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--dx-muted); font-weight: 700; padding-inline: 8px; }
.dx-nav ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.dx-nav a { display: block; padding: 5px 8px; font-size: 14px; color: var(--dx-fg); text-decoration: none; border-left: 2px solid transparent; }
.dx-nav a:hover { background: var(--dx-surface); }
.dx-nav a[aria-current="page"] { color: var(--dx-accent); font-weight: 700; border-left-color: var(--dx-accent); background: var(--dx-accent-soft); }
.dx-empty { color: var(--dx-muted); font-size: 14px; padding: 8px; }

.dx-main { min-width: 0; padding: 32px clamp(16px, 4vw, 56px) 80px; }
.dx-page { max-width: 1040px; display: flex; flex-direction: column; gap: 32px; }
.dx-eyebrow { font-size: 11px; letter-spacing: 1.4px; text-transform: uppercase; font-weight: 700; color: var(--dx-accent); }
.dx-page h1 { margin: 4px 0 8px; font-family: var(--dx-display); font-weight: 800; font-size: clamp(28px, 4vw, 40px); line-height: 1.15; text-wrap: balance; }
.dx-lead { margin: 0; font-size: 17px; color: var(--dx-muted); max-width: 68ch; }
.dx-sec { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.dx-sec h2 { margin: 0; font-family: var(--dx-display); font-weight: 700; font-size: 22px; line-height: 1.3; }
.dx-sec h3 { margin: 8px 0 0; font-size: 16px; font-weight: 700; }
.dx-sec p { margin: 0; max-width: 72ch; }
.dx-list { margin: 0; padding-left: 20px; display: flex; flex-direction: column; gap: 6px; max-width: 76ch; }

/* exemplo vivo */
.dx-stage { position: relative; border: 1px solid var(--dx-line); background: #ffffff; color: #1a1a2e; padding: 24px; overflow: auto; }
.dx-stage.is-wide { padding: 0; overflow: hidden; }
.dx-stage__inner { transform-origin: top left; width: 1440px; }
.dx-stage .ds-modal__backdrop { position: absolute; }
.dx-stage .dis-sidenav__sticky { position: static !important; height: auto !important; }
.dx-stage-err { padding: 16px; color: #b00020; font-family: var(--dx-mono); font-size: 12px; white-space: pre-wrap; }
.dx-stage-label { font-size: 12px; color: var(--dx-muted); display: flex; justify-content: space-between; margin-bottom: 6px; }

/* abas de código */
.dx-code { border: 1px solid var(--dx-code-line); background: var(--dx-code-bg); min-width: 0; }
.dx-tabs { display: flex; align-items: stretch; border-bottom: 1px solid var(--dx-code-line); overflow-x: auto; }
.dx-tab { border: 0; background: none; color: #93a3cc; padding: 10px 16px; cursor: pointer; font-size: 13px; font-weight: 600; white-space: nowrap; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.dx-tab:hover { color: #fff; }
.dx-tab[aria-selected="true"] { color: #fff; border-bottom-color: #8fb4ff; }
.dx-tabs__sp { flex: 1; }
.dx-copy { border: 0; background: none; color: #93a3cc; padding: 0 14px; cursor: pointer; font-size: 12px; white-space: nowrap; }
.dx-copy:hover { color: #fff; }
.dx-note { padding: 8px 16px; font-size: 12px; color: #93a3cc; border-bottom: 1px solid var(--dx-code-line); }
.dx-pre { margin: 0; padding: 16px; overflow: auto; max-height: 520px; font-family: var(--dx-mono); font-size: 12.5px; line-height: 1.65; color: var(--dx-code-fg); tab-size: 2; }
.dx-pre code { background: none; border: 0; padding: 0; font-size: inherit; }
.tk-c { color: var(--dx-tok-com); font-style: italic; } .tk-s { color: var(--dx-tok-str); } .tk-k { color: var(--dx-tok-kw); }
.tk-t { color: var(--dx-tok-tag); } .tk-a { color: var(--dx-tok-attr); } .tk-n { color: var(--dx-tok-num); }

/* tabelas */
.dx-tablewrap { overflow-x: auto; border: 1px solid var(--dx-line); }
.dx-table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
.dx-table th { text-align: left; background: var(--dx-surface); font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: var(--dx-muted); padding: 8px 12px; white-space: nowrap; }
.dx-table td { padding: 9px 12px; border-top: 1px solid var(--dx-line); vertical-align: top; }
.dx-table td:first-child code { white-space: nowrap; color: var(--dx-accent); }
.dx-table td.t-type code { background: none; border: 0; padding: 0; }

.dx-callout { border: 1px solid var(--dx-warn-line); background: var(--dx-warn-bg); padding: 12px 16px; font-size: 14px; max-width: 76ch; }
.dx-pn { display: flex; justify-content: space-between; gap: 12px; border-top: 1px solid var(--dx-line); padding-top: 16px; flex-wrap: wrap; }
.dx-pn a { text-decoration: none; font-weight: 600; }

/* fundamentos */
.dx-swatches { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 12px; }
.dx-sw { border: 1px solid var(--dx-line); min-width: 0; }
.dx-sw i { display: block; height: 52px; border-bottom: 1px solid var(--dx-line); }
.dx-sw div { padding: 8px 10px; font-size: 12px; }
.dx-sw b { display: block; font-family: var(--dx-mono); font-size: 12px; word-break: break-all; }
.dx-sw span { color: var(--dx-muted); display: block; }
.dx-sw small { color: var(--dx-muted); display: block; margin-top: 4px; line-height: 1.4; }
.dx-ramp { display: grid; grid-template-columns: repeat(auto-fit, minmax(54px, 1fr)); border: 1px solid var(--dx-line); }
.dx-ramp div { padding: 22px 4px 6px; font-size: 10px; font-family: var(--dx-mono); text-align: center; }
.dx-typerow { display: grid; grid-template-columns: 120px minmax(0, 1fr); gap: 16px; align-items: baseline; padding: 10px 0; border-top: 1px solid var(--dx-line); }
.dx-typerow small { font-family: var(--dx-mono); color: var(--dx-muted); font-size: 11px; line-height: 1.4; }
.dx-icons { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 8px; }
.dx-icon { border: 1px solid var(--dx-line); padding: 12px 8px; display: flex; flex-direction: column; align-items: center; gap: 8px; cursor: pointer; background: var(--dx-bg); text-align: center; }
.dx-icon:hover { border-color: var(--dx-accent); }
.dx-icon svg { width: 20px; height: 20px; fill: var(--dx-accent); }
.dx-icon b { font-family: var(--dx-mono); font-size: 11px; font-weight: 600; word-break: break-all; }
.dx-icon small { color: var(--dx-muted); font-size: 11px; }
.dx-space { display: flex; align-items: center; gap: 12px; padding: 6px 0; border-top: 1px solid var(--dx-line); font-size: 13px; }
.dx-space i { display: block; height: 14px; background: var(--dx-accent); flex: none; }
.dx-space code { min-width: 150px; }

.dx-hero { border: 1px solid var(--dx-line); background: var(--dx-surface); padding: clamp(20px, 4vw, 36px); display: grid; gap: 16px; }
.dx-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; }
.dx-card { display: flex; flex-direction: column; gap: 6px; border: 1px solid var(--dx-line); padding: 16px; text-decoration: none; color: var(--dx-fg); background: var(--dx-bg); }
.dx-card:hover { border-color: var(--dx-accent); }
.dx-card b { font-family: var(--dx-display); font-size: 16px; }
.dx-card span { color: var(--dx-muted); font-size: 13.5px; }
.dx-cmd { margin: 0; }

@media (max-width: 860px) {
  .dx-menu-btn { display: inline-grid; }
  .dx-stacks, .dx-ver { display: none; }
  .dx-shell { grid-template-columns: minmax(0, 1fr); }
  .dx-side { position: fixed; z-index: 25; inset: calc(56px + env(safe-area-inset-top, 0px)) 0 0 0; height: auto; width: min(320px, 88vw); transform: translateX(-100%); transition: transform .2s; box-shadow: 0 0 0 100vmax transparent; }
  .dx-side.is-open { transform: none; box-shadow: 0 0 0 100vmax rgba(0, 0, 0, .35); }
  .dx-typerow { grid-template-columns: minmax(0, 1fr); gap: 4px; }
}
@media (prefers-reduced-motion: reduce) { .dx-side { transition: none; } }
.dx-page h1 { overflow-wrap: anywhere; }
